<!DOCTYPE html>
<html>
<head>
<title>Snake Game</title>
<style>
body {
  background-color: #1e1e1e;
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
  margin: 0;
}

#snake-game {
  display: flex;
  gap: 20px;
}

.button {
  background-color: #333;
  border: none;
  padding: 10px 20px;
  font-size: 16px;
  color: white;
  cursor: pointer;
  border-radius: 5px;
}

#snake {
  width: 400px;
  height: 400px;
  border: 2px solid white;
  position: relative;
}
</style>
</head>
<body>
<div id="snake-game">
    <canvas id="snake" width="400" height="400"></canvas>
    <button id="start">Start</button>
    <button id="pause">Pause</button>
    <button id="reset">Reset</button>
    <div id="score">Score: 0</div>
</div>

<script>
const w = 16; // cell size
const h = 16;
let snake = [[w * 4, h * 4], [w * 4, h * 3], [w * 4, h * 2]];
let food = [w * 2, h * 2];
let score = 0;
let direction = 'right';
let gameInterval;

const snakeElement = document.getElementById('snake');
for (let i = 0; i < snake.length; i++) {
    const cell = document.createElement('div');
    cell.style.position = 'absolute';
    cell.style.width = w + 'px';
    cell.style.height = h + 'px';
    cell.style.border = '1px solid white';
    snakeElement.appendChild(cell);
}

const startButton = document.getElementById('start');
const pauseButton = document.getElementById('pause');
const resetButton = document.getElementById('reset');
const scoreDisplay = document.getElementById('score');

window.game = {
  w: w,
  h: h,
  reset: () => {
    snake = [[w * 4, h * 4], [w * 4, h * 3], [w * 4, h * 2]];
    food = [w * 2, h * 2];
    score = 0;
    direction = 'right';
    gameInterval = null;
    start();
  },
  tick: () => {
    if (!alive()) return;

    const head = snake[0];
    let newHead = [head[0], head[1]];

    switch (direction) {
      case 'up':
        newHead[1] -= 1;
        break;
      case 'down':
        newHead[1] += 1;
        break;
      case 'left':
        newHead[0] -= 1;
        break;
      case 'right':
        newHead[0] += 1;
        break;
    }

    if (newHead[0] < 0 || newHead[0] >= w || newHead[1] < 0 || newHead[1] >= h) {
      alive = false;
      return;
    }

    for (let i = 0; i < snake.length; i++) {
      if (snake[i][0] === newHead[0] && snake[i][1] === newHead[1]) {
        alive = false;
        return;
      }
    }

    snake.unshift(newHead);

    if (newHead[0] === food[0] && newHead[1] === food[1]) {
      score += 1;
      scoreDisplay.textContent = `Score: ${score}`;
      food = [Math.floor(Math.random() * w), Math.floor(Math.random() * h)];
    } else {
      snake.pop();
    }
  },
  setDir: (dir) => {
    if (direction === dir) return;
    direction = dir;
  },
  setFood: (x, y) => {
    food = [x, y];
  },
  snake: () => snake.map(cell => [cell[0], cell[1]]),
  food: () => food,
  alive: () => {
      return alive;
  },
  score: () => score
};

let alive = true;

function start() {
    if (gameInterval) clearTimeout(gameInterval);
    gameInterval = setInterval(window.game.tick, 150);
}

startButton.addEventListener('click', () => {
  start();
});

pauseButton.addEventListener('click', () => {
  clearInterval(gameInterval);
  gameInterval = null;
});

resetButton.addEventListener('click', () => {
  window.game.reset();
});


document.addEventListener('keydown', (event) => {
    if (!alive) return;
    switch (event.key) {
        case 'ArrowUp':
            window.game.setDir('up');
            break;
        case 'ArrowDown':
            window.game.setDir('down');
            break;
        case 'ArrowLeft':
            window.game.setDir('left');
            break;
        case 'ArrowRight':
            window.game.setDir('right');
            break;
    }
});
</script>
</body>
</html>
